import puppeteer from 'puppeteer-core';
const baseUrl=process.env.TEST_URL,executablePath=process.env.CHROME_PATH;if(!baseUrl||!executablePath)throw new Error('TEST_URL/CHROME_PATH missing');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const browser=await puppeteer.launch({executablePath,headless:true,args:['--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--no-first-run','--no-default-browser-check'],timeout:30000});
async function waitFor(fn,timeout=20000,step=100){const end=Date.now()+timeout;while(Date.now()<end){if(await fn())return true;await sleep(step)}return false}
async function makeClient(label,score=0){const context=await browser.createBrowserContext(),page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(String(e?.stack||e?.message||e)));page.on('console',m=>{if(m.type()==='error'&&!/Failed to load resource:.*404/i.test(m.text()))errors.push('console: '+m.text())});await page.evaluateOnNewDocument(({label,score})=>{try{localStorage.setItem('BombermanPlayerName',label);localStorage.setItem('BombermanRatingV1',String(score));localStorage.setItem('BombermanScoreV1Initialized','1');localStorage.setItem('BombermanMultiplayerAIEnabled','1');localStorage.setItem('BombermanAIDifficultyV1','normal')}catch(e){}try{if(navigator.serviceWorker)navigator.serviceWorker.register=()=>Promise.resolve({scope:location.href})}catch(e){}},{label,score});await page.goto(baseUrl,{waitUntil:'domcontentloaded',timeout:20000});await page.waitForFunction(()=>window.BomberV127&&BomberV127.version==='v0.12.7'&&window.BomberV124&&window.BomberV125&&window.BomberDataSync&&gGameEngine?.menu&&document.getElementById('mainSettingsTile'),{timeout:20000});return{context,page,errors,label}}
async function snap(page){return page.evaluate(()=>({role:B115.role,started:B115.started,score:BomberV127.getScore(),round:BomberV127.round(),players:gGameEngine.players.map(p=>({alive:p.alive})),bots:gGameEngine.bots.map(b=>({alive:b.alive,sim:!!b.simulatedHuman})),elim:!!document.getElementById('qolEliminated')&&!document.getElementById('qolEliminated').hidden,rematchNow:!!document.getElementById('v127RematchNow')&&!document.getElementById('v127RematchNow').hidden&&getComputedStyle(document.getElementById('v127RematchNow')).display!=='none',prompt:!!document.getElementById('qolRematchPrompt')&&!document.getElementById('qolRematchPrompt').hidden,post:!!document.getElementById('qolPostMatch')&&!document.getElementById('qolPostMatch').hidden,version:document.getElementById('buildVersion127')?.textContent}))}
async function connect(A,B,id){await A.page.evaluate(id=>{BomberV124.setAIEnabled(true);BomberV125.setDifficulty('normal');B115.privateId=()=>id;B115.els.privateCode.value='9';B115.els.name.value='Host127';B115.startPrivateHost()},id);await sleep(800);await B.page.evaluate(id=>{B115.privateId=()=>id;B115.els.privateCode.value='9';B115.els.name.value='Guest127';B115.startPrivateJoin()},id);const ok=await waitFor(async()=>{const[a,b]=await Promise.all([snap(A.page),snap(B.page)]);return a.started&&b.started&&a.role==='host'&&b.role==='guest'&&a.players.length===2&&b.players.length===2},25000,150);if(!ok)throw new Error('v127 pair did not connect');await sleep(900)}
async function close(c){await c?.context.close().catch(()=>{})}
let A,B,C;
try{
 C=await makeClient('Settings127',0);
 const main=await C.page.evaluate(()=>({version:document.getElementById('buildVersion127')?.textContent,tile:getComputedStyle(document.getElementById('mainSettingsTile')).display,hotLog:!!document.getElementById('v127LogList'),stableLog:!!document.getElementById('v127LogListDisplay')}));
 console.log('SETTINGS_MAIN',JSON.stringify(main));if(main.version!=='v0.12.7'||main.tile==='none'||main.hotLog||!main.stableLog)throw new Error('v0.12.7 settings/log UI did not initialize cleanly');
 await C.page.click('#mainSettingsTile');await sleep(100);let settings=await C.page.evaluate(()=>({hidden:document.getElementById('v127SettingsPanel').hidden,buttons:[...document.querySelectorAll('[data-v127-diff]')].map(b=>b.textContent),note:document.querySelector('#v127SettingsPanel .v127_section:nth-of-type(2) p')?.textContent||''}));if(settings.hidden||settings.buttons.join(',')!=='Easy,Normal,Hard,Expert'||!/This device only/i.test(settings.note))throw new Error('settings panel missing expected controls/accurate log scope');
 await C.page.click('[data-v127-diff="hard"]');await sleep(80);let diff=await C.page.evaluate(()=>({runtime:BomberV125.getDifficulty(),stored:localStorage.getItem('BombermanAIDifficultyV1')}));if(diff.runtime!=='hard'||diff.stored!=='hard')throw new Error('single-player AI difficulty did not persist');
 await C.page.evaluate(()=>{BomberV127.logEvent('SearchTester','Public search','Matched with Demo');BomberV127.renderLocalLog()});await sleep(60);let logText=await C.page.$eval('#v127LogListDisplay',e=>e.textContent);if(!/SearchTester/.test(logText)||!/Matched with Demo/.test(logText))throw new Error('local matchmaking log did not render');console.log('SETTINGS_LOG PASS');await close(C);C=null;

 A=await makeClient('Host127',100);B=await makeClient('Guest127',200);await connect(A,B,'bomberman-v127-'+Date.now());
 await A.page.evaluate(()=>gGameEngine.players[1].die());
 const duel=await waitFor(async()=>{const[a,b]=await Promise.all([snap(A.page),snap(B.page)]);return a.score===110&&b.score===190&&a.round.duelResolved&&b.round.duelResolved&&a.bots.filter(x=>!x.sim&&x.alive).length===2},7000,100);if(!duel){const[a,b]=await Promise.all([snap(A.page),snap(B.page)]);throw new Error('first-human duel scoring incorrect host='+JSON.stringify(a)+' guest='+JSON.stringify(b))}
 console.log('DUEL_SCORE PASS');
 await A.page.evaluate(()=>gGameEngine.players[0].die());
 const second=await waitFor(async()=>{const a=await snap(A.page);return a.score===110&&a.round.localEliminated},5000,100);if(!second)throw new Error('second human death changed score or did not enter rematch-eligible spectating');
 const secondButton=await waitFor(async()=>{const s=await snap(A.page);return s.elim&&s.rematchNow},6000,100);if(!secondButton)throw new Error('second-dead human did not receive Rematch now');
 await A.page.click('#v127RematchNow');
 const prompt=await waitFor(async()=>{const s=await snap(B.page);return s.prompt},5000,100);if(!prompt)throw new Error('Rematch now after second human death did not send a request');
 await B.page.click('#qolRematchAccept');
 const restarted=await waitFor(async()=>{const[a,b]=await Promise.all([snap(A.page),snap(B.page)]);return a.players.length===2&&b.players.length===2&&a.players.every(x=>x.alive)&&b.players.every(x=>x.alive)&&!a.round.duelResolved&&!b.round.duelResolved},9000,120);if(!restarted)throw new Error('accepted second-death rematch did not restart both clients');
 let[a,b]=await Promise.all([snap(A.page),snap(B.page)]);if(a.score!==110||b.score!==190)throw new Error('rematch altered settled scores');console.log('SECOND_DEATH_REMATCH PASS');
 await A.page.evaluate(()=>gGameEngine.players[1].die());await waitFor(async()=>{const[a,b]=await Promise.all([snap(A.page),snap(B.page)]);return a.score===120&&b.score===180&&a.round.duelResolved},6000,100);
 await A.page.evaluate(()=>{gGameEngine.bots.filter(b=>!b.simulatedHuman).slice().forEach(b=>b.die())});
 const bonus=await waitFor(async()=>{const s=await snap(A.page);return s.score===125&&s.round.aiBonusResolved},6000,100);if(!bonus){const s=await snap(A.page);throw new Error('AI clear did not award exactly +5: '+JSON.stringify(s))}
 a=await snap(A.page);b=await snap(B.page);if(a.score!==125||b.score!==180)throw new Error('AI bonus affected wrong player or double-counted round');console.log('AI_CLEAR_BONUS PASS');
 if([...A.errors,...B.errors].length)throw new Error('browser errors: '+[...A.errors,...B.errors].join(' | '));
 console.log('V127_REMATCH_SETTINGS_SMOKE PASS');
}finally{await close(A);await close(B);await close(C);await browser.close().catch(()=>{})}
